// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/plus-jakarta-sans";
import "@fontsource/noto-sans-kr";

export const plusJakartaSans = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { plusJakartaSans, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "BENTO";

/**
 * BENTO 벤토 — design that holds. The signature is an asymmetric bento grid:
 * rounded white tiles on a soft putty field, each spanning a different shape
 * (2×1, 1×2, a large feature, a small chip). A couple of tiles carry tiny
 * CSS-shape illustrations (a waveform, concentric rings, stacked bars); two
 * are color-accent tiles in the brand blue. On hover a tile lifts and scales
 * a touch — a FLIP-flavoured pop — while its neighbours settle back. The
 * wordmark is Plus Jakarta Sans 800, blue, each glyph rising into place.
 *
 * `.bento-js` is added on mount so the no-JS markup is the finished page:
 * every tile sits, copy is readable, the grid is whole without motion.
 */
export default function BentoPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const gridRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("bento-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "bento" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // FLIP-flavoured hover: when one tile is pointed, it scales up a touch and
  // its siblings dim slightly. Reduced motion skips the dim, keeps focus ring.
  useEffect(() => {
    if (reduced) return;
    const grid = gridRef.current;
    if (!grid) return;
    const tiles = Array.from(grid.querySelectorAll<HTMLElement>(".bento-tile"));
    const onEnter = (e: Event) => {
      const t = e.currentTarget as HTMLElement;
      for (const tile of tiles) {
        if (tile === t) tile.classList.add("bt-pop");
        else tile.classList.add("bt-dim");
      }
    };
    const onLeave = () => {
      for (const tile of tiles) {
        tile.classList.remove("bt-pop");
        tile.classList.remove("bt-dim");
      }
    };
    for (const t of tiles) {
      t.addEventListener("pointerenter", onEnter);
      t.addEventListener("pointerleave", onLeave);
    }
    return () => {
      for (const t of tiles) {
        t.removeEventListener("pointerenter", onEnter);
        t.removeEventListener("pointerleave", onLeave);
      }
    };
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${plusJakartaSans.variable} ${notoSansKR.variable} bento-root`}
    >
      <div className="bento-bg" aria-hidden="true" />
      <div ref={revealRef} className="bento-doc">
        <header className="bento-hero">
          <p className="bento-kicker">
            <span lang="ko">담는 디자인</span> · DESIGN THAT HOLDS
          </p>
          <h1 className="bento-title" aria-label={TITLE}>
            {TITLE.split("").map((ch, i) => (
              <span
                key={i}
                aria-hidden="true"
                className="bento-glyph"
                style={{ "--bt-i": i } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </h1>
          <p className="bento-title__ko" lang="ko">벤토</p>
          <p className="bento-sub">
            <span lang="ko">칸마다 하나의 이야기를 담는 그리드.</span>{" "}
            A grid where each compartment holds one story.
          </p>
        </header>

        <main>
          <section className="bento-lead" data-reveal>
            <p className="bento-lead__p">
              <span lang="ko">
                벤토는 나눔이 아니라 담음이다. 각 칸은 자기 크기를 가지고,
                서로 비워둔 여백 덕에 온전히 읽힌다. 복잡함을 숨기지 않고
                칸에 나누어 담는 것 — 그것이 우리가 부르는 정리다.
              </span>{" "}
              Bento is not dividing, it is holding. Each compartment owns its
              size, and the whitespace between them is what makes each legible.
              We don&apos;t hide complexity — we compartmentalise it.
            </p>
          </section>

          <section ref={gridRef} className="bento-grid" data-reveal>
            {/* Feature tile — large, brand blue. */}
            <article
              className="bento-tile bt-feature bt-accent"
              data-reveal
              style={{ "--bt-d": 40 } as CSSProperties}
            >
              <span className="bt-feature__n">01</span>
              <h2 className="bt-feature__en">Compartments</h2>
              <p className="bt-feature__ko" lang="ko">칸</p>
              <p className="bt-feature__p" lang="ko">
                하나의 칸은 하나의 생각. 넘치지 않고, 비지 않는 밀도.
              </p>
              {/* mini illustration: concentric rings */}
              <div className="bt-rings" aria-hidden="true">
                <span /><span /><span />
              </div>
            </article>

            {/* Tall tile — stacked bars illustration */}
            <article
              className="bento-tile bt-tall"
              data-reveal
              style={{ "--bt-d": 120 } as CSSProperties}
            >
              <span className="bt-tag">02</span>
              <div className="bt-bars" aria-hidden="true">
                <span style={{ height: "44%" }} />
                <span style={{ height: "72%" }} />
                <span style={{ height: "58%" }} />
                <span style={{ height: "90%" }} />
                <span style={{ height: "36%" }} />
              </div>
              <p className="bt-cap">
                <span lang="ko">밀도</span> · Density
              </p>
            </article>

            {/* Wide tile — waveform illustration */}
            <article
              className="bento-tile bt-wide"
              data-reveal
              style={{ "--bt-d": 80 } as CSSProperties}
            >
              <span className="bt-tag">03</span>
              <h3 className="bt-mid__en">Rhythm</h3>
              <p className="bt-mid__ko" lang="ko">박자</p>
              <div className="bt-wave" aria-hidden="true">
                <svg viewBox="0 0 200 40" preserveAspectRatio="none">
                  <path
                    d="M0,20 Q12,4 24,20 T48,20 T72,20 T96,20 T120,20 T144,20 T168,20 T192,20"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2.5"
                    strokeLinecap="round"
                  />
                </svg>
              </div>
            </article>

            {/* Small chip tiles */}
            <article
              className="bento-tile bt-chip"
              data-reveal
              style={{ "--bt-d": 160 } as CSSProperties}
            >
              <span className="bt-num">04</span>
              <span className="bt-chip__ko" lang="ko">여백</span>
              <span className="bt-chip__en">Margin</span>
            </article>

            <article
              className="bento-tile bt-chip bt-accent2"
              data-reveal
              style={{ "--bt-d": 200 } as CSSProperties}
            >
              <span className="bt-num">05</span>
              <span className="bt-chip__ko" lang="ko">정렬</span>
              <span className="bt-chip__en">Align</span>
            </article>

            {/* Quote tile — wide, soft */}
            <article
              className="bento-tile bt-quote"
              data-reveal
              style={{ "--bt-d": 240 } as CSSProperties}
            >
              <p className="bt-quote__p" lang="ko">
                &ldquo;담는다는 것은, 버리는 것이 아니라 자리를 주는 것이다.&rdquo;
              </p>
              <span className="bt-quote__by">— BENTO STUDIO</span>
            </article>

            {/* Number tile */}
            <article
              className="bento-tile bt-stat"
              data-reveal
              style={{ "--bt-d": 120 } as CSSProperties}
            >
              <span className="bt-stat__n">12</span>
              <span className="bt-stat__l" lang="ko">칸의 그리드</span>
            </article>

            {/* Footer-ish tile */}
            <article
              className="bento-tile bt-foot-tile"
              data-reveal
              style={{ "--bt-d": 200 } as CSSProperties}
            >
              <span className="bt-foot__ko" lang="ko">벤토 · 2026</span>
              <span className="bt-foot__en">BENTO · HOLD EVERYTHING</span>
            </article>
          </section>
        </main>

        <footer className="bento-foot">
          <span>BENTO · 2026</span>
          <span lang="ko">담는 디자인 — 서울 성수동</span>
        </footer>
      </div>
    </div>
  );
}

.bento-root {
  --bt-bg: #f4f5f7;
  --bt-bg2: #eceef2;
  --bt-ink: #0e1726;
  --bt-mute: #5b6678;
  --bt-line: #d9dde4;
  --bt-tile: #ffffff;
  --bt-blue: #2563eb;
  --bt-blue2: #1d4ed8;
  --bt-amber: #f59e0b;
  --bt-font-display: "Plus Jakarta Sans", system-ui, sans-serif;
  --bt-font-kr: "Noto Sans KR", sans-serif;
  --bt-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --bt-r: 24px;

  position: relative;
  min-height: 100vh;
  margin: 0;
  background: var(--bt-bg);
  color: var(--bt-ink);
  font-family: var(--bt-font-kr);
  font-weight: 400;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Atmospheric depth: a soft top sheen + a faint grid of dot light. */
.bento-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(60% 50% at 18% 0%, rgba(37, 99, 235, 0.10), transparent 70%),
    radial-gradient(55% 45% at 100% 12%, rgba(245, 158, 11, 0.08), transparent 72%),
    linear-gradient(180deg, var(--bt-bg2) 0%, var(--bt-bg) 30%, var(--bt-bg) 100%);
}
.bento-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(14, 23, 38, 0.045) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: linear-gradient(180deg, rgba(0,0,0,0.7), transparent 60%);
  -webkit-mask-image: linear-gradient(180deg, rgba(0,0,0,0.7), transparent 60%);
}

.bento-doc {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  margin: 0 auto;
  padding: clamp(1.25rem, 4vw, 3rem);
}

.bento-root ::selection {
  background: var(--bt-blue);
  color: #fff;
}

/* ---- Hero ---- */
.bento-hero {
  padding: clamp(2.5rem, 8vh, 5rem) 0 clamp(1.5rem, 4vw, 2.5rem);
}
.bento-kicker {
  margin: 0 0 1.2rem;
  font-family: var(--bt-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 600;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: var(--bt-blue);
}
.bento-kicker span[lang="ko"] { color: var(--bt-mute); margin-right: 0.5rem; }
.bento-title {
  margin: 0;
  font-family: var(--bt-font-display);
  font-weight: 800;
  font-size: clamp(3.6rem, 17vw, 13rem);
  line-height: 0.86;
  letter-spacing: -0.045em;
  text-transform: uppercase;
  color: var(--bt-blue);
  text-shadow: 0 16px 40px rgba(37, 99, 235, 0.22);
}
.bento-glyph { display: inline-block; }
.bento-title__ko {
  margin: 0.6rem 0 0;
  font-family: var(--bt-font-kr);
  font-weight: 500;
  font-size: clamp(1rem, 2.2vw, 1.5rem);
  letter-spacing: 0.5em;
  color: var(--bt-mute);
}
.bento-sub {
  margin: 1.4rem 0 0;
  max-width: 52ch;
  font-size: clamp(1rem, 1.7vw, 1.25rem);
}
.bento-sub span[lang="ko"] { display: block; color: var(--bt-mute); font-size: 0.84em; margin-bottom: 0.3rem; }

/* ---- Lead ---- */
.bento-lead {
  padding: clamp(1.5rem, 4vw, 2.5rem) 0;
  border-top: 1px solid var(--bt-line);
}
.bento-lead__p {
  margin: 0 auto;
  max-width: 60ch;
  font-size: clamp(1.05rem, 2vw, 1.45rem);
  line-height: 1.55;
}
.bento-lead__p span[lang="ko"] {
  display: block;
  color: var(--bt-mute);
  font-size: 0.82em;
  margin-bottom: 0.6em;
}

/* ---- Bento grid (asymmetric) ---- */
.bento-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: minmax(120px, auto);
  gap: clamp(0.8rem, 1.4vw, 1.1rem);
  padding-bottom: clamp(2rem, 5vw, 3rem);
}
.bento-tile {
  position: relative;
  grid-column: span 1;
  grid-row: span 1;
  padding: clamp(1.1rem, 2vw, 1.6rem);
  border-radius: var(--bt-r);
  background: var(--bt-tile);
  border: 1px solid var(--bt-line);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 18px 36px -28px rgba(14, 23, 38, 0.45);
  overflow: hidden;
  transition:
    transform 420ms var(--bt-ease),
    box-shadow 420ms var(--bt-ease),
    opacity 420ms var(--bt-ease),
    clip-path 700ms var(--bt-ease);
  clip-path: inset(0 0 0 0);
  cursor: default;
}
/* clip-path reveal: tiles wipe open from the top edge on mount. */
.bento-js [data-reveal].bento-tile { clip-path: inset(0 100% 0 0); }
.bento-js [data-reveal].bento-tile.is-visible { clip-path: inset(0 0 0 0); }

/* FLIP-flavoured hover pop. */
.bento-js .bt-pop {
  transform: scale(1.02);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 30px 50px -26px rgba(37, 99, 235, 0.45);
  z-index: 2;
}
.bento-js .bt-dim { opacity: 0.82; }

/* tile shapes */
.bt-feature { grid-column: span 2; grid-row: span 2; }
.bt-wide    { grid-column: span 2; }
.bt-tall    { grid-row: span 2; }
.bt-quote   { grid-column: span 2; }
.bt-foot-tile { grid-column: span 2; }

/* accent tiles */
.bento-tile.bt-accent {
  background: linear-gradient(150deg, var(--bt-blue) 0%, var(--bt-blue2) 100%);
  color: #f3f7ff;
  border-color: transparent;
}
.bento-tile.bt-accent2 {
  background: linear-gradient(150deg, #0e1726 0%, #1b2536 100%);
  color: #fff;
  border-color: transparent;
}

/* feature tile internals */
.bt-feature__n {
  font-family: var(--bt-font-display);
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.24em;
  opacity: 0.85;
}
.bt-feature__en {
  margin: 0.6rem 0 0;
  font-family: var(--bt-font-display);
  font-weight: 800;
  font-size: clamp(1.6rem, 3.4vw, 2.6rem);
  line-height: 1;
  letter-spacing: -0.02em;
}
.bt-feature__ko {
  margin: 0.2rem 0 0.9rem;
  font-family: var(--bt-font-kr);
  font-size: 1rem;
  letter-spacing: 0.3em;
  opacity: 0.85;
}
.bt-feature__p {
  margin: 0;
  max-width: 30ch;
  font-size: 0.92rem;
  opacity: 0.92;
}
.bt-rings {
  position: absolute;
  right: -30px;
  bottom: -30px;
  width: 150px;
  height: 150px;
}
.bt-rings span {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.4);
  transform: scale(calc(var(--s, 0.66) + 0.34));
}
.bt-rings span:nth-child(1) { --s: 0.00; }
.bt-rings span:nth-child(2) { --s: 0.34; border-color: rgba(255,255,255,0.28); }
.bt-rings span:nth-child(3) { --s: 0.66; border-color: rgba(255,255,255,0.18); }

/* tall tile — bars */
.bt-tall { display: flex; flex-direction: column; }
.bt-tall .bt-tag { font-family: var(--bt-font-display); font-weight: 700; font-size: 0.74rem; letter-spacing: 0.22em; color: var(--bt-blue); }
.bt-bars {
  flex: 1;
  display: flex;
  align-items: flex-end;
  gap: 6px;
  margin: 0.9rem 0 0.8rem;
  min-height: 90px;
  color: var(--bt-blue);
}
.bt-bars span {
  flex: 1;
  background: linear-gradient(180deg, var(--bt-blue) 0%, rgba(37,99,235,0.35) 100%);
  border-radius: 4px 4px 0 0;
  min-height: 8px;
}
.bt-cap { margin: 0; font-family: var(--bt-font-display); font-weight: 600; font-size: 0.92rem; }
.bt-cap span[lang="ko"] { color: var(--bt-mute); margin-right: 0.4rem; }

/* wide tile — wave */
.bt-wide { color: var(--bt-ink); }
.bt-wide .bt-tag { font-family: var(--bt-font-display); font-weight: 700; font-size: 0.74rem; letter-spacing: 0.22em; color: var(--bt-amber); }
.bt-mid__en { margin: 0.4rem 0 0; font-family: var(--bt-font-display); font-weight: 700; font-size: clamp(1.3rem, 2.6vw, 1.9rem); }
.bt-mid__ko { margin: 0; font-family: var(--bt-font-kr); color: var(--bt-mute); font-size: 0.92rem; letter-spacing: 0.18em; }
.bt-wave { margin-top: 0.9rem; color: var(--bt-blue); height: 40px; }
.bt-wave svg { width: 100%; height: 100%; display: block; }

/* chip tiles */
.bt-chip { display: flex; flex-direction: column; justify-content: space-between; min-height: 120px; }
.bt-num { font-family: var(--bt-font-display); font-weight: 700; font-size: 0.74rem; letter-spacing: 0.22em; opacity: 0.8; }
.bt-chip__ko { font-family: var(--bt-font-kr); font-weight: 500; font-size: 1.4rem; letter-spacing: 0.1em; }
.bt-chip__en { font-family: var(--bt-font-display); font-weight: 600; font-size: 0.8rem; letter-spacing: 0.16em; opacity: 0.85; text-transform: uppercase; }

/* quote tile */
.bt-quote {
  background: linear-gradient(160deg, #fff 0%, #f1f3f8 100%);
}
.bt-quote__p {
  margin: 0 0 0.8rem;
  font-family: var(--bt-font-display);
  font-weight: 500;
  font-size: clamp(1.05rem, 2vw, 1.45rem);
  line-height: 1.45;
  color: var(--bt-ink);
}
.bt-quote__by { font-family: var(--bt-font-display); font-size: 0.76rem; letter-spacing: 0.22em; color: var(--bt-blue); }

/* stat tile */
.bt-stat { display: flex; flex-direction: column; justify-content: flex-end; }
.bt-stat__n { font-family: var(--bt-font-display); font-weight: 800; font-size: clamp(2.4rem, 5vw, 3.4rem); line-height: 1; color: var(--bt-blue); }
.bt-stat__l { font-family: var(--bt-font-kr); font-size: 0.9rem; color: var(--bt-mute); margin-top: 0.3rem; }

/* footer tile */
.bt-foot-tile {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.3rem;
}
.bt-foot__ko { font-family: var(--bt-font-kr); font-weight: 500; font-size: 1.05rem; letter-spacing: 0.2em; }
.bt-foot__en { font-family: var(--bt-font-display); font-weight: 700; font-size: 0.76rem; letter-spacing: 0.24em; color: var(--bt-mute); text-transform: uppercase; }

.bento-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(1.5rem, 4vw, 2.5rem) 0;
  border-top: 1px solid var(--bt-line);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--bt-mute);
  font-family: var(--bt-font-display);
}

/* ---- Reveal gating ---- */
.bento-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--bt-ease), transform 800ms var(--bt-ease);
}
.bento-js [data-reveal].is-visible { opacity: 1; transform: none; }
.bento-js [data-reveal] { transition-delay: calc(var(--bt-d, 0) * 1ms); }
.bento-js .bento-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--bt-ease), transform 700ms var(--bt-ease);
  transition-delay: calc(var(--bt-i) * 70ms + 150ms);
}
.bento-js.is-mounted .bento-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .bento-js [data-reveal], .bento-js .bento-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important; clip-path: none !important;
  }
  .bento-js [data-reveal].bento-tile { clip-path: none !important; }
}

.bento-root :focus-visible {
  outline: 2px solid var(--bt-blue);
  outline-offset: 3px;
}

@media (max-width: 760px) {
  .bento-grid { grid-template-columns: repeat(2, 1fr); }
  .bt-feature { grid-column: span 2; grid-row: span 2; }
  .bt-wide, .bt-quote, .bt-foot-tile { grid-column: span 2; }
  .bt-tall { grid-row: span 1; }
}
